function formasDecodificar(s) {
  if (!s.length) return 0;
  let prev2 = 1, prev1 = s[0] === '0' ? 0 : 1;
  for (let i = 2; i <= s.length; i++) {
    let actual = 0;
    if (s[i - 1] !== '0') actual += prev1;
    const dos = Number(s.slice(i - 2, i));
    if (dos >= 10 && dos <= 26) actual += prev2;
    prev2 = prev1;
    prev1 = actual;
  }
  return prev1;
}

