def formasDecodificar(s):
    if not s:
        return 0
    prev2, prev1 = 1, (0 if s[0] == '0' else 1)
    for i in range(2, len(s) + 1):
        actual = 0
        if s[i - 1] != '0':
            actual += prev1
        if 10 <= int(s[i - 2:i]) <= 26:
            actual += prev2
        prev2, prev1 = prev1, actual
    return prev1
